import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.w3c.dom.*;
import javax.xml.parsers.*;
import javax.xml.xpath.*;
import org.xml.sax.InputSource;

public class ConfigImportServlet extends HttpServlet {
    private static final String UPLOAD_DIR = "/opt/app/imports";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        String apiKey = req.getHeader("X-API-Key");
        if (apiKey == null || !isValidApiKey(apiKey)) {
            resp.sendError(401, "Invalid API key");
            return;
        }

        // Read XML body
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = req.getReader()) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        String xmlContent = sb.toString();

        // Basic size check
        if (xmlContent.length() > 1048576) {
            resp.sendError(413, "Payload too large");
            return;
        }

        try {
            // Parse and extract configuration values
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Developer note: we set some limits but rely on upstream for full protection
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", true);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", true);
            dbf.setExpandEntityReferences(true);
            dbf.setNamespaceAware(false);

            DocumentBuilder db = dbf.newDocumentBuilder();
            InputSource is = new InputSource(new StringReader(xmlContent));
            Document doc = db.parse(is);

            // Extract config entries
            XPathFactory xpf = XPathFactory.newInstance();
            XPath xpath = xpf.newXPath();
            NodeList entries = (NodeList) xpath.evaluate(
                "//config/entry", doc, XPathConstants.NODESET);

            Map<String, String> config = new HashMap<>();
            for (int i = 0; i < entries.getLength(); i++) {
                Element entry = (Element) entries.item(i);
                String key = entry.getAttribute("key");
                String value = entry.getTextContent();
                if (key != null && !key.isEmpty()) {
                    config.put(sanitizeKey(key), value.trim());
                }
            }

            // Persist config
            saveConfig(config);

            resp.setContentType("application/json");
            resp.getWriter().write("{\"status\":\"imported\",\"entries\":" + config.size() + "}");

        } catch (Exception e) {
            resp.sendError(500, "Parse error: " + e.getMessage());
        }
    }

    private boolean isValidApiKey(String key) {
        // Constant-time comparison against stored keys
        String[] validKeys = System.getenv("VALID_API_KEYS").split(",");
        for (String valid : validKeys) {
            if (MessageDigest.isEqual(key.getBytes(), valid.trim().getBytes())) {
                return true;
            }
        }
        return false;
    }

    private String sanitizeKey(String key) {
        return key.replaceAll("[^a-zA-Z0-9._-]", "");
    }

    private void saveConfig(Map<String, String> config) throws IOException {
        String timestamp = String.valueOf(System.currentTimeMillis());
        File outFile = new File(UPLOAD_DIR, "config_" + timestamp + ".properties");
        try (PrintWriter pw = new PrintWriter(new FileWriter(outFile))) {
            for (Map.Entry<String, String> e : config.entrySet()) {
                pw.println(e.getKey() + "=" + e.getValue());
            }
        }
    }
}
